#!/usr/bin/env node
/**
 * Copies the design tokens generated by the Stage 1 design pipeline
 * (.design-foundations/tokens/generated/, written by build-tokens.mjs from
 * kiwi-ui.tokens.json) into src/theme/generated/, so the app builds from files
 * inside kiwi-ui and never reaches outside its own folder at build time.
 *
 *   node scripts/sync-design-tokens.mjs           copy every generated file
 *   node scripts/sync-design-tokens.mjs --check   exit 1 when a copy is missing or differs
 *
 * The copies are byte-for-byte; src/theme/generated/generated.test.ts fails when
 * they drift from the design source. Never edit a copy by hand: change the token
 * source, run the design pipeline, then this script.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const UI_ROOT = join(here, "..");
export const SOURCE_DIR = join(UI_ROOT, "..", ".design-foundations", "tokens", "generated");
export const TARGET_DIR = join(UI_ROOT, "src", "theme", "generated");

/** Every generated output the app consumes, relative to both directories. */
export const GENERATED_FILES = [
  "kiwi-ui.tokens.css",
  "mui-theme.json",
  "code-themes/ace-kiwi-light.css",
  "code-themes/ace-kiwi-dark.css",
  "code-themes/prism-kiwi.json",
  "code-themes/console.css",
];

/** Returns the files whose copy is missing or differs from its source. */
export function staleCopies() {
  return GENERATED_FILES.filter((file) => {
    const target = join(TARGET_DIR, file);
    if (!existsSync(target)) return true;
    return !readFileSync(join(SOURCE_DIR, file)).equals(readFileSync(target));
  });
}

function main(argv) {
  if (!existsSync(SOURCE_DIR)) {
    console.error(`sync-design-tokens: no design source at ${relative(UI_ROOT, SOURCE_DIR)}`);
    return 1;
  }
  const missing = GENERATED_FILES.filter((file) => !existsSync(join(SOURCE_DIR, file)));
  if (missing.length) {
    console.error(`sync-design-tokens: the design source lacks ${missing.join(", ")}`);
    return 1;
  }

  if (argv.includes("--check")) {
    const stale = staleCopies();
    if (stale.length) {
      console.error(`sync-design-tokens: stale copies: ${stale.join(", ")}. Run npm run tokens:sync.`);
      return 1;
    }
    console.log(`sync-design-tokens: ${GENERATED_FILES.length} copies match the design source`);
    return 0;
  }

  for (const file of GENERATED_FILES) {
    const target = join(TARGET_DIR, file);
    mkdirSync(dirname(target), { recursive: true });
    copyFileSync(join(SOURCE_DIR, file), target);
  }
  console.log(`sync-design-tokens: copied ${GENERATED_FILES.length} files into ${relative(UI_ROOT, TARGET_DIR)}`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main(process.argv.slice(2));
}
